From 67ba1903caf5244516bd55f4cdcc8ae639646852 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:47:34 +0100
Subject: [PATCH] klipper: keep images that are not saved when deleting history
 entries

With images not saved, the history didn't know a copied image was in the
clipboard, so deleting the last entry cleared it. Now buffers holding
skipped images are tracked like passwords and left alone in that case.

BUG: 452287
---
 klipper/historymodel.cpp | 27 +++++++++++++++++++++------
 klipper/historymodel.h   |  6 +++++-
 2 files changed, 26 insertions(+), 7 deletions(-)

diff --git a/klipper/historymodel.cpp b/klipper/historymodel.cpp
index 8112dadb5b..843af9a442 100644
--- a/klipper/historymodel.cpp
+++ b/klipper/historymodel.cpp
@@ -233,17 +233,18 @@ HistoryModel::HistoryModel()
     });

     connect(this, &HistoryModel::changed, this, [this](bool isTop) {
-        const SystemClipboard::SelectionMode buffersWithoutPassword = buffersHolding(Holding::NoPassword);
-        // Nothing to restore into: both buffers hold a password, which is never in the history.
-        if (buffersWithoutPassword == 0) {
+        const SystemClipboard::SelectionMode buffersFromHistory =
+            SystemClipboard::SelectionMode(buffersHolding(Holding::NoPassword) & ~buffersHolding(Holding::UnsavedData));
+        // Nothing to restore into: both buffers hold a password or unsaved data, which is never in the history.
+        if (buffersFromHistory == 0) {
             return;
         }

         if (m_items.empty()) {
             // The history is empty (user might have deleted the last history entry manually).
-            // Empty the buffers too, except the ones holding a password.
+            // Empty the buffers too, except the ones holding a password or unsaved data.
             // Clearing the history explicitly does wipe passwords, in clear().
-            m_clip->clear(buffersWithoutPassword);
+            m_clip->clear(buffersFromHistory);
             return;
         }
         if (!isTop) {
@@ -258,7 +259,7 @@ HistoryModel::HistoryModel()
                 return;
             }
             // Only restore buffers that did not contain passwords.
-            m_clip->setMimeData(m_items[0], buffersWithoutPassword);
+            m_clip->setMimeData(m_items[0], buffersFromHistory);
         }
     });

@@ -396,10 +397,16 @@ void HistoryModel::clearHasPassword()
 {
     setHasPassword(QClipboard::Clipboard, false);
     setHasPassword(QClipboard::Selection, false);
+    setHasUnsavedData(QClipboard::Clipboard, false);
+    setHasUnsavedData(QClipboard::Selection, false);
 }

 SystemClipboard::SelectionMode HistoryModel::buffersHolding(Holding holding) const
 {
+    if (holding == Holding::UnsavedData) {
+        return SystemClipboard::SelectionMode((m_clipboardHasUnsavedData ? SystemClipboard::Clipboard : 0)
+                                              | (m_selectionHasUnsavedData ? SystemClipboard::Selection : 0));
+    }
     const bool password = holding == Holding::APassword;
     return SystemClipboard::SelectionMode((m_clipboardHasPassword == password ? SystemClipboard::Clipboard : 0)
                                           | (m_selectionHasPassword == password ? SystemClipboard::Selection : 0));
@@ -1063,6 +1070,7 @@ void HistoryModel::checkClipData(QClipboard::Mode mode, const QMimeData *data)
         return;
     }
     setHasPassword(mode, false);
+    setHasUnsavedData(mode, false);

     if (selectionMode && !m_bSaveSelection) {
         // Even when selection is not saved, we are configured to sync it
@@ -1078,6 +1086,7 @@ void HistoryModel::checkClipData(QClipboard::Mode mode, const QMimeData *data)
     }

     if (!m_bSaveImages && data->hasImage() && !data->hasText() /*BUG 491488*/ && !data->hasFormat(QStringLiteral("x-kde-force-image-copy"))) {
+        setHasUnsavedData(mode, true);
         return;
     }

@@ -1104,6 +1113,7 @@ void HistoryModel::slotReceivedEmptyClipboard(QClipboard::Mode mode)
                             SystemClipboard::ClipboardUpdateReason::PreventEmptyClipboard);
     }
     setHasPassword(mode, false);
+    setHasUnsavedData(mode, false);
 }

 bool HistoryModel::isItemStarred(const QString &uuid) const
@@ -1138,6 +1148,11 @@ void HistoryModel::setHasPassword(QClipboard::Mode mode, bool hasPassword)
     Q_EMIT hasPasswordChanged();
 }

+void HistoryModel::setHasUnsavedData(QClipboard::Mode mode, bool hasUnsavedData)
+{
+    (mode == QClipboard::Selection ? m_selectionHasUnsavedData : m_clipboardHasUnsavedData) = hasUnsavedData;
+}
+
 void HistoryModel::setURLGrabber(URLGrabber *grabber)
 {
     m_urlGrabber = grabber;
diff --git a/klipper/historymodel.h b/klipper/historymodel.h
index 15fe0f0f68..c808eb0f30 100644
--- a/klipper/historymodel.h
+++ b/klipper/historymodel.h
@@ -154,12 +154,14 @@ private:
     bool isItemStarred(const QString &uuid) const;

     void setHasPassword(QClipboard::Mode mode, bool hasPassword);
+    void setHasUnsavedData(QClipboard::Mode mode, bool hasUnsavedData);

     enum class Holding {
         APassword,
         NoPassword,
+        UnsavedData,
     };
-    /** The system buffers that are either holding a password, or that have no password. */
+    /** The system buffers that are holding a password, that have no password, or that hold data skipped by the history. */
     [[nodiscard]] SystemClipboard::SelectionMode buffersHolding(Holding holding) const;

     std::shared_ptr<SystemClipboard> m_clip;
@@ -178,6 +180,8 @@ private:
     bool m_bActionOnSelection = true;
     bool m_clipboardHasPassword = false;
     bool m_selectionHasPassword = false;
+    bool m_clipboardHasUnsavedData = false;
+    bool m_selectionHasUnsavedData = false;

     friend class DeclarativeHistoryModel;
     friend class HistoryModelTest;
